// NewStatusPayload builds a ai service status endpoint payload.
func NewStatusPayload(cookie string) *ai.StatusPayload {
	v := &ai.StatusPayload{}
	v.Cookie = cookie

	return v
}

// NewRunPayload builds a ai service run endpoint payload.
func NewRunPayload(body *RunRequestBody, cookie string) *ai.RunPayload {
	v := &ai.RunPayload{
		Question:  *body.Question,
		SessionID: body.SessionID,
	}
	if body.Page != nil {
		v.Page = unmarshalAIPageRequestBodyToAiAIPage(body.Page)
	}
	v.Cookie = cookie

	return v
}

// NewRunsPayload builds a ai service runs endpoint payload.
func NewRunsPayload(limit int, sessionID *string, cookie string) *ai.RunsPayload {
	v := &ai.RunsPayload{}
	v.Limit = limit
	v.SessionID = sessionID
	v.Cookie = cookie

	return v
}

