// NewUpdateConversationPayload builds a ai service updateConversation endpoint
// payload.
func NewUpdateConversationPayload(body *UpdateConversationRequestBody, sessionID string, cookie string) *ai.UpdateConversationPayload {
	v := &ai.UpdateConversationPayload{
		Title:    body.Title,
		Archived: body.Archived,
	}
	v.SessionID = sessionID
	v.Cookie = cookie

	return v
}

// ValidateRunRequestBody runs the validations defined on RunRequestBody
func ValidateRunRequestBody(body *RunRequestBody) (err error) {
	if body.Question == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("question", "body"))
	}
	if body.Question != nil {
		if utf8.RuneCountInString(*body.Question) < 1 {
			err = goa.MergeErrors(err, goa.InvalidLengthError("body.question", *body.Question, utf8.RuneCountInString(*body.Question), 1, true))
		}
		if utf8.RuneCountInString(*body.Question) > 4000 {
			err = goa.MergeErrors(err, goa.InvalidLengthError("body.question", *body.Question, utf8.RuneCountInString(*body.Question), 4000, false))
		}
	}
	if body.SessionID != nil {
		if utf8.RuneCountInString(*body.SessionID) > 80 {
			err = goa.MergeErrors(err, goa.InvalidLengthError("body.sessionId", *body.SessionID, utf8.RuneCountInString(*body.SessionID), 80, false))
		}
	}
	if body.Page != nil {
		if err2 := validateAIPageRequestBody(body.Page, "body.page"); err2 != nil {
			err = goa.MergeErrors(err, err2)
		}
	}
	return
}

// ValidateUpdateConversationRequestBody runs the validations defined on
// UpdateConversationRequestBody
func ValidateUpdateConversationRequestBody(body *UpdateConversationRequestBody) (err error) {
	if body.Title != nil {
		if utf8.RuneCountInString(*body.Title) < 1 {
			err = goa.MergeErrors(err, goa.InvalidLengthError("body.title", *body.Title, utf8.RuneCountInString(*body.Title), 1, true))
		}
		if utf8.RuneCountInString(*body.Title) > 200 {
			err = goa.MergeErrors(err, goa.InvalidLengthError("body.title", *body.Title, utf8.RuneCountInString(*body.Title), 200, false))
		}
	}
	return
}

// ValidateAIPageRequestBody runs the validations defined on AIPage
func ValidateAIPageRequestBody(body *AIPageRequestBody) (err error) {
	if body.Route != nil {
		if utf8.RuneCountInString(*body.Route) > 120 {
			err = goa.MergeErrors(err, goa.InvalidLengthError("body.route", *body.Route, utf8.RuneCountInString(*body.Route), 120, false))
		}
	}
	if body.Entity != nil {
		if utf8.RuneCountInString(*body.Entity) > 40 {
			err = goa.MergeErrors(err, goa.InvalidLengthError("body.entity", *body.Entity, utf8.RuneCountInString(*body.Entity), 40, false))
		}
	}
	if body.EntityID != nil {
		if *body.EntityID < 0 {
			err = goa.MergeErrors(err, goa.InvalidRangeError("body.entityId", *body.EntityID, 0, true))
		}
	}
	return
}

// validateAIPageRequestBody checks AIPage and reports errors using the path
// supplied by its caller
func validateAIPageRequestBody(body *AIPageRequestBody, path string) (err error) {
	if body.Route != nil {
		if utf8.RuneCountInString(*body.Route) > 120 {
			err = goa.MergeErrors(err, goa.InvalidLengthError(path+".route", *body.Route, utf8.RuneCountInString(*body.Route), 120, false))
		}
	}
	if body.Entity != nil {
		if utf8.RuneCountInString(*body.Entity) > 40 {
			err = goa.MergeErrors(err, goa.InvalidLengthError(path+".entity", *body.Entity, utf8.RuneCountInString(*body.Entity), 40, false))
		}
	}
	if body.EntityID != nil {
		if *body.EntityID < 0 {
			err = goa.MergeErrors(err, goa.InvalidRangeError(path+".entityId", *body.EntityID, 0, true))
		}
	}
	return
}
